//! Runs the scripts in `tests/lua51` with `Compat::Lua51` and compares their output with the
//! output of PUC-Rio Lua 5.1.5 (`*.out`, regenerated by `tests/lua51/regen.sh`).
//!
//! `print` writes to a buffer instead of stdout, and is defined in Lua with `tostring`, so the
//! scripts also test it. `newproxy` makes a userdata, as 5.1's does.

use std::{cell::RefCell, fs, rc::Rc};

use lunita::{Callback, CallbackReturn, Closure, Compat, Executor, Lua, String, Table, UserData};

fn run_script(name: &str, source: &[u8]) -> Vec<u8> {
    // The mode is set before the library loads, as a host does (`_VERSION` is set by it).
    let mut lua = Lua::empty();
    lua.set_compat(Compat::Lua51);
    lua.load_core().unwrap();
    let output = Rc::new(RefCell::new(Vec::new()));

    let out = output.clone();
    let executor = lua.try_enter(|ctx| {
        let out = out.clone();
        ctx.set_global(
            "__write",
            Callback::from_fn(&ctx, move |ctx, _, mut stack| {
                let s: String = stack.consume(ctx)?;
                out.borrow_mut().extend_from_slice(s.as_bytes());
                Ok(CallbackReturn::Return)
            }),
        )
        .unwrap();
        // Lua 5.1's `newproxy`: a userdata, with a new metatable when asked for one.
        ctx.set_global(
            "newproxy",
            Callback::from_fn(&ctx, |ctx, _, mut stack| {
                let with_metatable = stack.get(0).to_bool();
                let ud = UserData::new_static(&ctx, ());
                if with_metatable {
                    ud.set_metatable(&ctx, Some(Table::new(&ctx)));
                }
                stack.replace(ctx, ud);
                Ok(CallbackReturn::Return)
            }),
        )
        .unwrap();
        let prelude = Closure::load(
            ctx,
            Some("prelude"),
            &b"
                function print(...)
                    local n = select('#', ...)
                    for i = 1, n do
                        if i > 1 then __write('\\t') end
                        __write(tostring((select(i, ...))))
                    end
                    __write('\\n')
                end
                loadstring = load
                io = {
                    write = function(...)
                        for i = 1, select('#', ...) do
                            __write(tostring((select(i, ...))))
                        end
                    end,
                }
            "[..],
        )?;
        let script = Closure::load(ctx, Some(name), source)?;
        Ok((
            ctx.stash(Executor::start(ctx, prelude.into(), ())),
            ctx.stash(script),
        ))
    });
    let (prelude, script) = match executor {
        Ok(executor) => executor,
        Err(err) => return format!("<compile error: {err}>\n").into_bytes(),
    };
    lua.execute::<()>(&prelude).unwrap();
    let executor = lua.enter(|ctx| {
        let script = ctx.fetch(&script);
        ctx.stash(Executor::start(ctx, script.into(), ()))
    });
    if let Err(err) = lua.execute::<()>(&executor) {
        output
            .borrow_mut()
            .extend_from_slice(format!("<error: {err}>\n").as_bytes());
    }
    let output = output.borrow().clone();
    output
}

#[test]
fn lua51_scripts() {
    let mut failures = Vec::new();
    let mut paths = fs::read_dir("tests/lua51")
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|e| e == "lua"))
        .collect::<Vec<_>>();
    paths.sort();
    for path in paths {
        let name = path.file_name().unwrap().to_string_lossy().into_owned();
        let source = fs::read(&path).unwrap();
        let expected = fs::read(path.with_extension("out")).unwrap();
        let actual = run_script(&name, &source);
        if actual != expected {
            let (actual, expected) = (
                std::string::String::from_utf8_lossy(&actual),
                std::string::String::from_utf8_lossy(&expected),
            );
            let line = actual
                .lines()
                .zip(expected.lines())
                .position(|(a, e)| a != e)
                .unwrap_or_else(|| actual.lines().count().min(expected.lines().count()));
            failures.push(format!(
                "{name}: output differs at line {}:\n  lunita: {:?}\n  PUC 5.1: {:?}",
                line + 1,
                actual.lines().nth(line).unwrap_or("<end>"),
                expected.lines().nth(line).unwrap_or("<end>"),
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
